-- Generated by `prisma migrate dev --create-only` as one statement:
--   ALTER TABLE "customer" ADD COLUMN "tier" TEXT NOT NULL;
-- which fails on a table with rows. Edited by hand into three steps.

-- 1. Add the column as nullable.
ALTER TABLE "customer" ADD COLUMN "tier" TEXT;

-- 2. Data migration: fill it from the existing "active" column.
UPDATE "customer" SET "tier" = CASE WHEN "active" = 1 THEN 'standard' ELSE 'inactive' END;

-- 3. Now every row has a value, so the column can be required.
ALTER TABLE "customer" ALTER COLUMN "tier" SET NOT NULL;
